-- Title: HackTool - LaZagne Execution
-- ID: c2b86e67-b880-4eec-b045-50bc98ef4844
-- Status: experimental
-- Level: medium
-- Author: Nasreddine Bencherchali, Swachchhanda Shrawan Poudel (Nextron Systems)
-- Date: 2024-06-24
-- Tags: attack.credential-access
-- Description: Detects the execution of the LaZagne. A utility used to retrieve multiple types of passwords stored on a local computer.
-- LaZagne has been leveraged multiple times by threat actors in order to dump credentials.
-- Converted by: Sigma Universal SIEM/EDR CLI

SELECT * FROM processes WHERE ((((Image LIKE '%:\\PerfLogs\\%' OR Image LIKE '%:\\ProgramData\\%' OR Image LIKE '%:\\Temp\\%' OR Image LIKE '%:\\Tmp\\%' OR Image LIKE '%:\\Users\\Public\\%' OR Image LIKE '%:\\Windows\\Temp\\%' OR Image LIKE '%\\$Recycle.bin%' OR Image LIKE '%\\AppData\\%' OR Image LIKE '%\\Desktop\\%' OR Image LIKE '%\\Downloads\\%' OR Image LIKE '%\\Favorites\\%' OR Image LIKE '%\\Links\\%' OR Image LIKE '%\\Music\\%' OR Image LIKE '%\\Photos\\%' OR Image LIKE '%\\Pictures\\%' OR Image LIKE '%\\Saved Games\\%' OR Image LIKE '%\\Searches\\%' OR Image LIKE '%\\Users\\Contacts\\%' OR Image LIKE '%\\Users\\Default\\%' OR Image LIKE '%\\Users\\Searches\\%' OR Image LIKE '%\\Videos\\%' OR Image LIKE '%\\Windows\\addins\\%' OR Image LIKE '%\\Windows\\Fonts\\%' OR Image LIKE '%\\Windows\\IME\\%') AND (CommandLine="*.exe all" OR CommandLine="*.exe browsers" OR CommandLine="*.exe chats" OR CommandLine="*.exe databases" OR CommandLine="*.exe games" OR CommandLine="*.exe git" OR CommandLine="*.exe mails" OR CommandLine="*.exe maven" OR CommandLine="*.exe memory" OR CommandLine="*.exe multimedia" OR CommandLine="*.exe sysadmin" OR CommandLine="*.exe unused" OR CommandLine="*.exe wifi" OR CommandLine="*.exe windows")) OR (Image="*\\lazagne.exe")) OR (((CommandLine LIKE '% all %' OR CommandLine LIKE '% browsers %' OR CommandLine LIKE '% chats %' OR CommandLine LIKE '% databases %' OR CommandLine LIKE '% games %' OR CommandLine LIKE '% mails %' OR CommandLine LIKE '% maven %' OR CommandLine LIKE '% memory %' OR CommandLine LIKE '% multimedia %' OR CommandLine LIKE '% php %' OR CommandLine LIKE '% svn %' OR CommandLine LIKE '% sysadmin %' OR CommandLine LIKE '% unused %' OR CommandLine LIKE '% wifi %')) AND ((CommandLine LIKE '%-1Password%' OR CommandLine LIKE '%-apachedirectorystudio%' OR CommandLine LIKE '%-autologon%' OR CommandLine LIKE '%-ChromiumBased%' OR CommandLine LIKE '%-coreftp%' OR CommandLine LIKE '%-credfiles%' OR CommandLine LIKE '%-credman%' OR CommandLine LIKE '%-cyberduck%' OR CommandLine LIKE '%-dbvis%' OR CommandLine LIKE '%-EyeCon%' OR CommandLine LIKE '%-filezilla%' OR CommandLine LIKE '%-filezillaserver%' OR CommandLine LIKE '%-ftpnavigator%' OR CommandLine LIKE '%-galconfusion%' OR CommandLine LIKE '%-gitforwindows%' OR CommandLine LIKE '%-hashdump%' OR CommandLine LIKE '%-iisapppool%' OR CommandLine LIKE '%-IISCentralCertP%' OR CommandLine LIKE '%-kalypsomedia%' OR CommandLine LIKE '%-keepass%' OR CommandLine LIKE '%-keepassconfig%' OR CommandLine LIKE '%-lsa_secrets%' OR CommandLine LIKE '%-mavenrepositories%' OR CommandLine LIKE '%-memory_dump%' OR CommandLine LIKE '%-Mozilla%' OR CommandLine LIKE '%-mRemoteNG%' OR CommandLine LIKE '%-mscache%' OR CommandLine LIKE '%-opensshforwindows%' OR CommandLine LIKE '%-openvpn%' OR CommandLine LIKE '%-outlook%' OR CommandLine LIKE '%-pidgin%' OR CommandLine LIKE '%-postgresql%' OR CommandLine LIKE '%-psi-im%' OR CommandLine LIKE '%-puttycm%' OR CommandLine LIKE '%-pypykatz%' OR CommandLine LIKE '%-Rclone%' OR CommandLine LIKE '%-rdpmanager%' OR CommandLine LIKE '%-robomongo%' OR CommandLine LIKE '%-roguestale%' OR CommandLine LIKE '%-skype%' OR CommandLine LIKE '%-SQLDeveloper%' OR CommandLine LIKE '%-squirrel%' OR CommandLine LIKE '%-tortoise%' OR CommandLine LIKE '%-turba%' OR CommandLine LIKE '%-UCBrowser%' OR CommandLine LIKE '%-unattended%' OR CommandLine LIKE '%-vault%' OR CommandLine LIKE '%-vaultfiles%' OR CommandLine LIKE '%-vnc%' OR CommandLine LIKE '%-winscp%'))))
